"""Illustrated, bilingual concepts for the first lesson (static HTML first)."""
import json
from html import escape as e


def picture(kind):
    shapes={
      'computer':'<rect x="58" y="23" width="184" height="99" rx="8"/><path d="M73 105h154M130 123v19h40v-19M108 144h84"/><path d="m105 58 12 12-12 12m27 0h35"/>',
      'cpu':'<rect x="97" y="24" width="106" height="112" rx="12"/><rect x="117" y="47" width="66" height="64" rx="6"/>'+''.join(f'<path d="M{x} 13v11m0 112v11M86 {x-70}h11m106 0h11"/>' for x in (113,137,161,185)),
      'gpu':'<rect x="48" y="29" width="206" height="102" rx="10"/>'+''.join(f'<rect x="{x}" y="{y}" width="21" height="21" rx="3"/>' for x in (66,99,132,165,198) for y in (45,78))+'<path d="M75 141h155"/>',
      'ram':'<rect x="34" y="50" width="232" height="64" rx="6"/>'+''.join(f'<rect x="{x}" y="64" width="32" height="32" rx="3"/>' for x in (50,98,146,194))+''.join(f'<path d="M{x} 115v12"/>' for x in range(48,260,13)),
      'storage':'<rect x="80" y="22" width="140" height="119" rx="10"/><rect x="99" y="42" width="42" height="40" rx="4"/><rect x="159" y="42" width="42" height="40" rx="4"/><path d="M100 102h100m-100 16h68"/>',
      'disk':'<rect x="80" y="18" width="140" height="126" rx="10"/><circle cx="150" cy="79" r="43"/><circle cx="150" cy="79" r="11"/><path d="m211 128-49-40 10-10 39 50"/>',
      'architecture':'<rect x="104" y="14" width="92" height="46" rx="5"/><rect x="104" y="99" width="92" height="46" rx="5"/><rect x="12" y="56" width="65" height="46" rx="5"/><rect x="223" y="56" width="65" height="46" rx="5"/><path d="M135 61v37m29-37v37M77 79h28m91 0h27M116 38h66m-66 85h66"/>',
      'mcu':'<rect x="65" y="17" width="170" height="131" rx="10"/><rect x="81" y="35" width="62" height="48" rx="4"/><rect x="157" y="35" width="61" height="48" rx="4"/><rect x="81" y="99" width="137" height="30" rx="4"/><path d="M145 59h10M99 85v12m100-12v12"/>',
      'board':'<rect x="50" y="19" width="200" height="125" rx="8"/><rect x="74" y="38" width="62" height="60" rx="5"/><path d="M164 37v87m20-87v87m20-87v87M73 118h65"/><rect x="38" y="44" width="24" height="37"/>',
      'power':'<rect x="62" y="23" width="161" height="116" rx="8"/><circle cx="125" cy="79" r="37"/><path d="m128 48-19 38h22l-12 26m106-56h24v26h23m-49 20h19v21h30"/>',
      'io':'<path d="M78 83h50m-12-10 12 10-12 10m62-10h45m-12-10 12 10-12 10"/><rect x="18" y="55" width="59" height="54" rx="5"/><circle cx="153" cy="83" r="25"/><rect x="224" y="51" width="58" height="52" rx="5"/><path d="M252 105v15m-17 0h35M33 70h28M33 85h18"/>',
      'port':'<rect x="46" y="57" width="93" height="50" rx="23"/><rect x="60" y="70" width="65" height="24" rx="11"/><path d="M161 57h82l12 13v24l-12 13h-82zM177 74h55m-55 16h55"/>',
      'isa':'<rect x="36" y="26" width="89" height="115" rx="5"/><path d="M51 50h56M51 73h40M51 96h50M143 82h27m-10-9 10 9-10 9"/><rect x="185" y="47" width="73" height="71" rx="7"/><path d="M202 35v12m19-12v12m19-12v12M202 118v12m19-12v12m19-12v12"/>'
    }
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 164"><rect width="300" height="164" rx="14" fill="#f0eefb"/><g stroke="#6558b4" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" fill="#fff">'+shapes[kind]+'</g></svg>'


def render_concepts(root):
    data=json.loads((root/'content/concepts.json').read_text(encoding='utf-8'))
    folder=root/'assets/images/concepts';folder.mkdir(parents=True,exist_ok=True)
    for kind in {x['art'] for x in data}:(folder/f'{kind}.svg').write_text(picture(kind),encoding='utf-8')
    cards=[]
    for item in data:
        cards.append(f'''<details class="explore-card" data-concept-group="{item['group']}" id="concept-{item['id']}"><summary><img src="../assets/images/concepts/{item['art']}.svg" alt="" width="300" height="164"><span class="explore-title">{e(item['title'])}</span><span class="explore-english" lang="en">{e(item['english'])}</span><span class="explore-short">{e(item['short'])}</span><span class="explore-open">İncele <span aria-hidden="true">＋</span></span></summary><div class="explore-detail"><h4>Nasıl çalışır?</h4><p>{e(item['detail'])}</p><h4>Gerçek sistemde</h4><p>{e(item['example'])}</p><p class="explore-note"><strong>Karıştırma:</strong> {e(item['note'])}</p></div></details>''')
    return '''<div class="concept-explorer"><p class="muted">Bir kartı açın: İngilizce adını öğrenin, nasıl çalıştığını keşfedin ve gerçek bir sistemdeki görevini inceleyin.</p><div class="concept-filters" hidden aria-label="Kavram kategorileri"><button data-concept-filter="all" aria-pressed="true">Tümü</button><button data-concept-filter="compute" aria-pressed="false">İşleme & Mimari</button><button data-concept-filter="memory" aria-pressed="false">Bellek & Depolama</button><button data-concept-filter="system" aria-pressed="false">Donanım & Bağlantı</button></div><p class="concept-count" data-concept-count aria-live="polite"></p><div class="explore-grid">'''+''.join(cards)+'''</div><p class="concept-caption">Görseller kavramsal çizimlerdir; belirli bir ürünün fotoğrafı veya ölçekli devre şeması değildir.</p><section class="concept-lab" aria-labelledby="parallel-title"><span class="eyebrow">DENEYEREK ÖĞREN</span><h3 id="parallel-title">CPU ve GPU: aynı iş, farklı yaklaşım</h3><p>CPU (<span lang="en">Central Processing Unit</span>) genel amaçlı kontrol ve hesaplama için; GPU (<span lang="en">Graphics Processing Unit</span>) çok sayıda benzer işlemi paralel yürütmek için tasarlanır.</p><p>12 bağımsız piksele aynı işlemi uyguladığınızı düşünün. Aşağıdaki modelde bir akış adım başına 1, diğer düzen 4 piksel işler.</p><div class="parallel-display"><div><h4>Tek akışlı yaklaşım</h4><div class="task-pixels" data-cpu-pixels aria-hidden="true"></div><p data-cpu-result>0 / 12 piksel</p></div><div><h4>Paralel yaklaşım</h4><div class="task-pixels" data-gpu-pixels aria-hidden="true"></div><p data-gpu-result>0 / 12 piksel</p></div></div><div class="lab-controls" hidden><button data-parallel-step>Bir adım ilerlet →</button><button data-parallel-reset>Başa al</button><output data-parallel-status aria-live="polite">Henüz işlem yapılmadı.</output></div><noscript><p>Birinci adımda 1 ve 4; üçüncü adımda 3 ve 12 piksel işlenmiş olur. Bu bir hız ölçümü değildir.</p></noscript><p class="explore-note">Bu görsel bir paralellik modelidir, performans testi değildir. CPU da çok çekirdek ve vektör komutlarıyla paralel çalışabilir. GPU her görevde daha hızlı değildir; veri aktarımı, bağımlılıklar ve yazılım sonucu etkiler.</p></section><section class="concept-lab" aria-labelledby="memory-title"><span class="eyebrow">KÜÇÜK BİR BELLEK DENEYİ</span><h3 id="memory-title">RAM mi, depolama mı?</h3><p>RAM çalışma masanız, SSD kayıtlı dosyaların durduğu dolabınız gibi düşünülebilir. Önce değeri değiştirin; kaydetmeden ve kaydettikten sonra güç kesintisini deneyin.</p><div class="memory-display"><div><span class="eyebrow">RAM · ÇALIŞMA KOPYASI</span><output data-memory-ram>24 °C</output><small>Güç kesilince kaybolur.</small></div><span class="memory-arrow" aria-hidden="true">→</span><div><span class="eyebrow">SSD · KAYITLI DOSYA</span><output data-memory-disk>24 °C</output><small>Güç kesilince korunur.</small></div></div><div class="memory-controls" hidden><button data-memory-edit>RAM’de değeri +1 artır</button><button data-memory-save>SSD’ye kaydet</button><button data-memory-power>Gücü kes</button><button data-memory-reset>Deneyi sıfırla</button></div><p data-memory-status role="status">Başlangıç: dosyadan RAM’e 24 °C yüklendi.</p><p class="concept-caption">Yalnızca sayfa içi simülasyon. Cihazınızın gücünü, belleğini veya dosyalarını değiştirmez. Yeniden açma adımı dosyanın RAM’e tekrar yüklenmesini temsil eder; otomatik kayıt varsayılmaz.</p></section><div class="concept-reading"><h3>Kaynaklarla pekiştir</h3><ul><li><a href="https://www.intel.com/content/www/us/en/products/docs/processors/cpu-vs-gpu.html">Intel · CPU ve GPU</a></li><li><a href="https://www.arm.com/glossary/isa">Arm · Instruction Set Architecture</a></li><li><a href="https://www.kingston.com/en/blog/pc-performance/difference-between-memory-storage">Kingston · Bellek ve depolama</a></li></ul></div></div>'''
